@Configuration
@ConfigurationProperties(prefix = "app.io")
public class NioConfigurationProperties {
    private int workerThreads = Runtime.getRuntime().availableProcessors() * 2;
    private int socketTimeoutMs = 5000;
    private boolean tcpNoDelay = true;

    // Standard getters and setters required for property binding
    public int getWorkerThreads() { return workerThreads; }
    public void setWorkerThreads(int workerThreads) { this.workerThreads = workerThreads; }
    public int getSocketTimeoutMs() { return socketTimeoutMs; }
    public void setSocketTimeoutMs(int socketTimeoutMs) { this.socketTimeoutMs = socketTimeoutMs; }
    public boolean isTcpNoDelay() { return tcpNoDelay; }
    public void setTcpNoDelay(boolean tcpNoDelay) { this.tcpNoDelay = tcpNoDelay; }
}
